import React, { useState } from "react";
import { motion } from "framer-motion";
import { BarChart, Bar, XAxis, YAxis, Tooltip, ResponsiveContainer } from "recharts";

export default function App() {

  const [disease, setDisease] = useState("");
  const [intent, setIntent] = useState("");
  const [location, setLocation] = useState("");

  const [data, setData] = useState(null);
  const [loading, setLoading] = useState(false);
  const [step, setStep] = useState("");

  // ✅ NEW FILTER STATE
  const [filters, setFilters] = useState({
    publications: true,
    trials: true,
    risk: true
  });

  const toggleFilter = (key) => {
    setFilters(prev => ({
      ...prev,
      [key]: !prev[key]
    }));
  };

  const handleRun = async () => {
    setLoading(true);
    setData(prev => prev); // don't clear immediately

    setStep("🔍 Fetching research...");
    setTimeout(() => setStep("📊 Ranking publications..."), 800);
    setTimeout(() => setStep("🤖 Generating AI summary..."), 1200);

    try {
      const res = await fetch("http://localhost:8000/analyze", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ disease, intent, location })
      });

      const result = await res.json();
      setData(result);

    } catch (err) {
      alert("❌ Backend not connected");
    }

    setLoading(false);
    setStep("");
  };

    const chartData = safeData.publications.length > 0
  ? [
      {
        name: "Results",
        Papers: safeData.publications.length,
        Trials: safeData.clinical_trials.length
      }
    ]
  : [];

  const riskScore = data
    ? Math.min(90, (data.publications?.length || 0) * 10)
    : 0;

  return (
    <motion.div style={container}>

      {/* LEFT PANEL */}
      <div style={leftPanel}>
        <h2>Curalink X</h2>

        <input
          placeholder="Filter by disease"
          value={disease}
          onChange={(e) => setDisease(e.target.value)}
          style={input}
        />

        <h3>Stats</h3>
        <p>📄 Papers: {data?.publications?.length || 0}</p>
        <p>🧪 Trials: {data?.clinical_trials?.length || 0}</p>

        {/* ✅ FILTER UI */}
        <h3 style={{ marginTop: "20px" }}>Insight Filters</h3>

        <label style={filterItem}>
          <input
            type="checkbox"
            checked={filters.publications}
            onChange={() => toggleFilter("publications")}
          />
          Publications
        </label>

        <label style={filterItem}>
          <input
            type="checkbox"
            checked={filters.trials}
            onChange={() => toggleFilter("trials")}
          />
          Clinical Trials
        </label>

        <label style={filterItem}>
          <input
            type="checkbox"
            checked={filters.risk}
            onChange={() => toggleFilter("risk")}
          />
          Risk Analysis
        </label>
      </div>

      {/* CENTER PANEL */}
      <div style={centerPanel}>
        <h1>🧠 AI Medical Research Copilot</h1>

        <textarea
          placeholder="Ask your medical research question..."
          value={intent}
          onChange={(e) => setIntent(e.target.value)}
          style={textarea}
        />

        <motion.button onClick={handleRun} style={button}>
          {loading ? "Running..." : "Send message"}
        </motion.button>

        <input
          placeholder="Location"
          value={location}
          onChange={(e) => setLocation(e.target.value)}
          style={input}
        />

        {loading && <p>⏳ {step}</p>}
      </div>

      {/* RIGHT PANEL */}
      <div style={rightPanel}>

       {data && chartData.length > 0 && filters.publications && (
  <motion.div style={card}>
    <h3>📊 Research Analytics</h3>

    {/* FIX: force stable container */}
    <div style={{ width: "100%", height: 220, minHeight: 220 }}>
      <ResponsiveContainer width="100%" height="100%">
        <BarChart data={chartData || []}>
          <XAxis dataKey="name" stroke="#ccc" />
          <YAxis stroke="#ccc" />
          <Tooltip />
          <Bar dataKey="Papers" fill="#3b82f6" />
          <Bar dataKey="Trials" fill="#8b5cf6" />
        </BarChart>
      </ResponsiveContainer>
    </div>
  </motion.div>
)}

        {/* ⚠️ RISK */}
        {filters.risk && (
          <div style={card}>
            <h3>⚠️ Risk Confidence</h3>
            <p>{riskScore}%</p>
          </div>
        )}

        {/* SUMMARY */}
        <div style={card}>
          <h3>Dynamic Insights</h3>
          {!data && <p>No data yet</p>}
          {data && <p>{data.summary}</p>}
        </div>

        {/* PAPERS */}
        {filters.publications && (
          <div style={card}>
            <h3>Research Papers</h3>

            {data?.publications?.map((p, i) => (
              <div key={i} style={item}>
                <strong>{p.title}</strong>
                <p style={meta}>{p.source} • {p.year}</p>
              </div>
            ))}
          </div>
        )}

        {/* TRIALS */}
        {filters.trials && (
          <div style={card}>
            <h3>Clinical Trials</h3>

            {data?.clinical_trials?.map((t, i) => (
              <div key={i} style={item}>
                <strong>{t.title}</strong>
                <p style={meta}>{t.status}</p>
              </div>
            ))}
          </div>
        )}

      </div>
    </motion.div>
  );
}

/* STYLE ADDITION */
